function calcEMA(a,p){const k=2/(p+1),e=[a[0]];for(let i=1;i<a.length;i++)e.push(a[i]*k+e[i-1]*(1-k));return e}
function calcRSI(c,p){p=p||14;if(c.length<p+1)return 50;let g=0,l=0;for(let i=c.length-p;i<c.length;i++){const d=c[i]-c[i-1];d>=0?g+=d:l-=d}const rs=(g/p)/((l/p)||1);return 100-100/(1+rs)}
