function calcATR(h,l,c,p){p=p||14;if(c.length<p+1)return 0;const tr=[];for(let i=1;i<c.length;i++)tr.push(Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1])));let atr=tr.slice(0,p).reduce((a,b)=>a+b,0)/p;for(let i=p;i<tr.length;i++)atr=(atr*(p-1)+tr[i])/p;return atr}
function calcADX(h,l,c,p){p=p||14;if(c.length<p*2+1)return{adx:25,plusDI:50,minusDI:50};const tr=[],pd=[],md=[];for(let i=1;i<c.length;i++){const t=Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1])),u=h[i]-h[i-1],d=l[i-1]-l[i];tr.push(t);pd.push((u>d&&u>0)?u:0);md.push((d>u&&d>0)?d:0)}let st=tr.slice(0,p).reduce((a,b)=>a+b,0),sp=pd.slice(0,p).reduce((a,b)=>a+b,0),sm=md.slice(0,p).reduce((a,b)=>a+b,0);const dx=[];let lp=0,lm=0;for(let i=p;i<tr.length;i++){st=st-(st/p)+tr[i];sp=sp-(sp/p)+pd[i];sm=sm-(sm/p)+md[i];const pi=100*(sp/(st||1)),mi=100*(sm/(st||1));dx.push(100*Math.abs(pi-mi)/((pi+mi)||1));lp=pi;lm=mi}if(dx.length<p)return{adx:25,plusDI:50,minusDI:50};let adx=dx.slice(0,p).reduce((a,b)=>a+b,0)/p;for(let i=p;i<dx.length;i++)adx=(adx*(p-1)+dx[i])/p;return{adx:adx,plusDI:lp,minusDI:lm}}
function detectCandlePattern(o,h,l,c){if(c.length<2)return null;const i=c.length-1,op=o[i],hi=h[i],lo=l[i],cl=c[i],po=o[i-1],pc=c[i-1],body=Math.abs(cl-op),uw=hi-Math.max(cl,op),lw=Math.min(cl,op)-lo;if(pc<po&&cl>op&&cl>pc&&op<pc)return'Бычье поглощение';if(pc>po&&cl<op&&cl<pc&&op>pc)return'Медвежье поглощение';if(body>0&&lw>body*2&&uw<body*0.5)return'Молот';if(body>0&&uw>body*2&&lw<body*0.5)return'Падающая звезда';return null}
