async function analyzeForScanner(a){if(getTwelveKeys().length===0||!a.td)throw new Error('Нет ключей');const tf=await getBestTimeframe(a),d=await fetchTwelveData('time_series','symbol='+encodeURIComponent(a.td)+'&interval='+tf+'&outputsize=100');if(!d.values||d.values.length<50)throw new Error('Мало данных');const v=d.values.slice().reverse(),o=[],h=[],l=[],c=[],vo=[];v.forEach(x=>{o.push(parseFloat(x.open));h.push(parseFloat(x.high));l.push(parseFloat(x.low));c.push(parseFloat(x.close));vo.push(parseFloat(x.volume)||0)});const last=c[c.length-1],ema9=calcEMA(c,9),ema21=calcEMA(c,21),ema50=calcEMA(c,50),rsi=calcRSI(c,14),sr=calcStochRSI(c,14,14),macd=calcMACD(c),adx=calcADX(h,l,c,14),bb=calcBollingerBands(c,20,2),pat=detectCandlePattern(o,h,l,c),atr=calcATR(h,l,c,14),e9=ema9[ema9.length-1],e21=ema21[ema21.length-1],e50=ema50.length?ema50[ema50.length-1]:e21;let sc=0;if(e9>e21&&e21>e50)sc+=2;else if(e9<e21&&e21<e50)sc-=2;else if(e9>e21)sc+=1;else sc-=1;if(macd.macd>macd.signal&&macd.histogram>0)sc+=1;else if(macd.macd<macd.signal&&macd.histogram<0)sc-=1;if(macd.crossover==='bull')sc+=0.5;if(macd.crossover==='bear')sc-=0.5;const os=(rsi<30?1:0)+(sr<20?1:0),ob=(rsi>70?1:0)+(sr>80?1:0);if(os===2)sc+=1.5;else if(os===1)sc+=0.7;if(ob===2)sc-=1.5;else if(ob===1)sc-=0.7;if(last>bb.upper&&sc>0)sc-=1;if(last<bb.lower&&sc<0)sc+=1;if(adx.adx>25){if(adx.plusDI>adx.minusDI)sc+=0.7;else sc-=0.7}else if(adx.adx<20)sc*=0.3;if(pat){if(pat.includes('Бычье')||pat.includes('Молот'))sc+=1.5;if(pat.includes('Медвежье')||pat.includes('звезда'))sc-=1.5}const dir=sc>=1?'UP':sc<=-1?'DOWN':'WAIT',as=Math.abs(sc);let cf=Math.min(99,Math.round(as*14+22));if(adx.adx<20)cf=Math.max(15,cf-15);return{dir:dir,confidence:cf,last:last,rsi:rsi,adx:adx.adx,atrPct:last?(atr/last*100):0,tf:tf}}
